    def findLongestWord(self, s, dictionary):
        """
        :type s: str
        :type dictionary: List[str]
        :rtype: str
        """
        ans = ""
        for t in dictionary:
            p1 = p2 = 0
            while p1 < len(s) and p2 < len(t):
                if s[p1] == t[p2]:
                    p2 += 1
                p1 += 1
            if p2 == len(t):
                if len(t) > len(ans) or (len(t) == len(ans) and t < ans):
                    ans = t
        return ans
